from typing import Collection, Tuple, TypeVar

from .bound import INF, Bound
from .charclass import (
    DIGIT,
    NONDIGITCHAR,
    NONSPACECHAR,
    NONWORDCHAR,
    SPACECHAR,
    WORDCHAR,
    Charclass,
    escapes,
    shorthand,
)
