    def to_fsm(self, /) -> Fsm:
        return Fsm.concatenate(EPSILON, *(mult.to_fsm() for mult in self.mults))

    def empty(self, /) -> bool:
        return any(mult.empty() for mult in self.mults)

    def __str__(self, /) -> str:
